import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题","docId":"user.preferences.faq","translationKey":"user.preferences.faq","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","translationRevision":"e3fd98ac05e0394b08373326b30a9a634a1dd84fe5c1d0346d5de10b88f5a34d","order":40},"headers":[],"relativePath":"zh/user/preferences/faq.md","filePath":"zh/user/preferences/faq.md","lastUpdated":1794611623000}'),o={name:"zh/user/preferences/faq.md"};function n(i,e,d,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="frequently-asked-questions" tabindex="-1">常见问题 <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;常见问题 {#frequently-asked-questions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>修改数据或凭据前，先解决常见工作流程疑问。下面的检查需要运行中的桌面应用；支持的安装包见<a href="./../requirements.html">系统要求</a>。除非明确说明实验性或服务依赖限制，此处讨论的本地功能均可使用。</p><h2 id="does-cloud-sign-in-connect-tiktok" tabindex="-1">登录 Cloud 会连接 TikTok 吗？ <a class="header-anchor" href="#does-cloud-sign-in-connect-tiktok" aria-label="Permalink to &quot;登录 Cloud 会连接 TikTok 吗？ {#does-cloud-sign-in-connect-tiktok}&quot;">​</a></h2><p>不会。请打开 <a href="./../live/connections.html">连接</a>，选择主播并单独启动直播连接。Cloud 身份用于基于账户的服务。TikTok Cookie 只能填写在指定的遮蔽连接字段中。</p><h2 id="why-is-a-connected-feed-empty" tabindex="-1">为什么连接成功后事件流仍为空？ <a class="header-anchor" href="#why-is-a-connected-feed-empty" aria-label="Permalink to &quot;为什么连接成功后事件流仍为空？ {#why-is-a-connected-feed-empty}&quot;">​</a></h2><p>安静的直播间可能没有新事件。选择全部事件、清空搜索并恢复滚动，再检查连接状态。暂停滚动不会停止接收或自动化。清空事件流不会重置积分或已持久化的统计。</p><h2 id="are-statistics-only-for-this-session" tabindex="-1">统计仅覆盖当前会话吗？ <a class="header-anchor" href="#are-statistics-only-for-this-session" aria-label="Permalink to &quot;统计仅覆盖当前会话吗？ {#are-statistics-only-for-this-session}&quot;">​</a></h2><p>当前<a href="./../points/statistics.html">统计页面</a>查询所选主播及日期范围的持久化聚合数据。扩大日期并刷新，可查看已记录的历史。它不是完整聊天记录。积分余额使用不同规则，可能包含手动或自动化调整。</p><h2 id="where-are-templates-variables-and-rankings" tabindex="-1">模板、变量与排行榜在哪里？ <a class="header-anchor" href="#where-are-templates-variables-and-rankings" aria-label="Permalink to &quot;模板、变量与排行榜在哪里？ {#where-are-templates-variables-and-rankings}&quot;">​</a></h2><p>模板和配置位于 <a href="./../automations/templates.html">自动化</a>；插件探索请求的是插件。运行时值位于自动化变量。实验性排名与竞赛工作区仍有 <code>#/rankings</code> 路由，但不在主导航及启动恢复中显示。常规积分榜与事件流排名面板是独立视图。</p><h2 id="does-saving-synchronize-everything" tabindex="-1">保存会同步所有内容吗？ <a class="header-anchor" href="#does-saving-synchronize-everything" aria-label="Permalink to &quot;保存会同步所有内容吗？ {#does-saving-synchronize-everything}&quot;">​</a></h2><p>不会。事件/操作更改比较本地参考。变量保存保持在本地，支持时另有经过审查的发送、采纳或撤回操作。秘密值比较会遮蔽内容。Cloud 叠加层使用创建、修订和库操作；此版本没有共享叠加层更改适配器。选择方向前请阅读<a href="./../cloud/changes.html">变更</a>。</p><h2 id="are-tests-harmless-and-do-imports-run-immediately" tabindex="-1">测试是否无害？导入后会立即运行吗？ <a class="header-anchor" href="#are-tests-harmless-and-do-imports-run-immediately" aria-label="Permalink to &quot;测试是否无害？导入后会立即运行吗？ {#are-tests-harmless-and-do-imports-run-immediately}&quot;">​</a></h2><p>测试可能执行实际效果，包括音频、网络请求和积分变更。请从 <a href="./../automations/first-rule.html">core.log</a> 开始。导入定义会保持禁用；请审查后明确激活。安装插件后，也需完成服务配置才能使用操作。</p><h2 id="expected-result-and-recovery" tabindex="-1">预期结果与恢复 <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;预期结果与恢复 {#expected-result-and-recovery}&quot;">​</a></h2><p>这些检查应能定位负责的页面，无需重置。自动检查更新是可选项；自动安装仍属实验性，并被当前发布门控禁用。完整远程协作及生产昵称搜索仍依赖部署与验收。如果仍有疑问，请通过<a href="./backups.html">备份</a>保存数据，并收集包含版本、时间和复现步骤的<a href="./troubleshooting.html">诊断报告</a>。</p>',17)])])}const p=a(o,[["render",n]]);export{f as __pageData,p as default};
